# B02: the problem. One held-out Huawei function (pri-60, day 12), 18:50-19:20, HPA at a 70% target:
# requests jump at 19:00, the first new server serves 3 minutes later, late requests in between.
# --------------------------------------------------------------------------------------------
class B02_Problem(Scene):
    BID, DEFAULT = "B02", 16.21

    def construct(self):
        self.begin()
        W = E["window"]
        n, m0, jump = len(W["load"]), W["start_minute"], 10
        target = round(100 * W["target"])
        hl = headline("A burst a fixed target cannot catch", "A burst a fixed", "target misses")
        if PORTRAIT:   # no y label: the key says "requests per minute"
            ylab = VGroup()
            box = Box(-SX + 0.82, hl.get_bottom()[1] - 1.42, SX - 0.05, hl.get_bottom()[1] - 0.3, (0, n), (0, 20000))
            xt = [(jump, hhmm(m0 + jump)), (25, hhmm(m0 + 25))]
        else:
            ylab = stack("requests per minute,", "one held-out Huawei function", size=26, color=SLATE, buff=0.04)
            place(ylab, left=-SX, top=hl.get_bottom()[1] - 0.25)
            box = Box(-SX + 1.0, -1.75, 0.8, ylab.get_bottom()[1] - 0.2, (0, n), (0, 20000))
            xt = [(i, hhmm(m0 + i)) for i in (0, 10, 20, 30)]
        ax = axes(box, [(0, ""), (10000, "10k"), (20000, "20k")], xt)
        pre = VGroup(box.steps(W["load"], 0, jump, SLATE), box.steps(W["capacity"], 0, jump, CRIMSON))
        post = VGroup(box.steps(W["load"], jump - 1, n, SLATE), box.steps(W["capacity"], jump - 1, n, CRIMSON))
        late = VGroup(*[box.column(i + 0.5, 0, v, 0.8, AQUA) for i, v in enumerate(W["late"]) if v > 0])
        k_req = swatch(SLATE, "requests a minute" if PORTRAIT else "requests")
        k_late = swatch(AQUA, "late requests", kind="dot")
        k_hpa = swatch(CRIMSON, f"HPA's servers, {target}% target" if not PORTRAIT else f"HPA at {target}% target")
        ready = next(i for i in range(jump, n) if W["capacity"][i] > W["capacity"][jump - 1])
        yb = 14000 if PORTRAIT else 16500   # the boot bracket: from the jump to the first new server serving
        brace = VGroup(Line(box.p(jump, yb), box.p(ready, yb), stroke_color=SLATE, stroke_width=5),
                       Line(box.p(jump, yb - 1000), box.p(jump, yb + 1000), stroke_color=SLATE, stroke_width=5),
                       Line(box.p(ready, yb - 1000), box.p(ready, yb + 1000), stroke_color=SLATE, stroke_width=5))
        blab = VGroup() if PORTRAIT else place(T(f"{ready - jump} min", 26, weight="BOLD"), right=box.p(jump, 0)[0] - 0.12, y=box.p(0, yb)[1])
        sp = 4   # spare before the burst
        spare = DoubleArrow(box.p(sp + 0.5, W["load"][sp]), box.p(sp + 0.5, W["capacity"][sp]), buff=0, stroke_color=SLATE,
                            stroke_width=5, tip_length=0.12, max_tip_length_to_length_ratio=0.35)
        slab = VGroup() if PORTRAIT else place(T("spare", 26, weight="BOLD"), right=spare.get_left()[0] - 0.12,
                                               y=box.p(0, (W["load"][sp] + W["capacity"][sp]) / 2)[1])
        pct = E["burst_first_minute_pct"]["azure"]
        spare_pct = 100 - target
        if PORTRAIT:
            keys = VGroup(k_req, k_hpa, k_late).arrange(DOWN, buff=0.05, aligned_edge=LEFT)
            place(keys, left=-SX, top=box.y0 - 0.4)
            items = [T(f"{W['jump']:.1f}x jump at {hhmm(m0 + jump)}", 26, weight="BOLD"),
                     T(f"{ready - jump} minutes to boot", 26, weight="BOLD"),
                     stack(f"{pct}% of Azure bursts", "peak in minute one", size=26, buff=0.04),
                     T(f"{spare_pct}% spare, all day", 26, weight="BOLD")]
            column(items, keys.get_bottom()[1] - 0.22, TEXT_FLOOR, left=-SX, min_gap=0.1)
        else:
            def item(big, *small):
                return VGroup(T(big, 40, weight="BOLD"), stack(*small, size=26, color=SLATE, buff=0.13)).arrange(DOWN, buff=0.08, aligned_edge=LEFT)
            items = [item(f"{W['jump']:.1f}x", "requests jump", "in one minute"),
                     item(f"{ready - jump} min", "until HPA's first new", "server serves"),
                     item(f"{pct}%", "of bursts peak in their", "first minute (Azure)"),
                     item(f"{spare_pct}%", f"spare at a {target}% target,", "the same all day")]
            column(items, hl.get_bottom()[1] - 0.3, -SY + 0.1, left=1.6, min_gap=0.15)
            keys = VGroup(VGroup(k_req, k_late).arrange(RIGHT, buff=0.4), k_hpa).arrange(DOWN, buff=0.1, aligned_edge=LEFT)
            place(keys, left=-SX, top=box.y0 - 0.55)
        self.P(FadeIn(hl), FadeIn(ax), FadeIn(ylab), FadeIn(keys), rt=0.8)
        self.P(Create(pre), rt=1.0)
        self.at(0.3)
        self.P(Create(post), rt=1.4)
        self.P(LaggedStart(*[GrowFromEdge(b, DOWN) for b in late], lag_ratio=0.15), FadeIn(items[0]), rt=0.8)
        self.at(0.48)
        self.P(Create(brace), FadeIn(blab), FadeIn(items[1]), rt=0.6)
        self.at(0.62)
        self.P(FadeIn(items[2]), rt=0.5)
        self.at(0.8)
        self.P(GrowFromCenter(spare), FadeIn(slab), FadeIn(items[3]), rt=0.6)
        self.end()


# --------------------------------------------------------------------------------------------
# B03: the method (train.py Headroom): each minute PPO picks HPA's target (40-90%) and HPA's rule turns it
# into servers. What it sees (env.py): the last 10 minutes, yesterday's and last week's next 10 minutes
# (drawn from the same function at 19:00), servers running and booting, queue, time of day.
# Portrait shows the flow first, then the inputs in its place.
# --------------------------------------------------------------------------------------------
class B03_Method(Scene):
    BID, DEFAULT = "B03", 15.17

    def construct(self):
        self.begin()
        W, targets = E["window"], [f"{int(round(t * 100))}%" for t in E["targets"]]
        hl = headline("PPO picks HPA's target", "PPO picks", "HPA's target")
        size = 26 if PORTRAIT else 28
        agent = chip("PPO", size=size, weight="BOLD", pad=0.1 if PORTRAIT else 0.16)
        spell = (stack("Proximal Policy Optimization,", "a reinforcement learning (RL)", "algorithm", size=26, color=SLATE, buff=0.04)
                 if not PORTRAIT else stack("Proximal Policy", "Optimization, a", "RL algorithm", size=26, color=SLATE, buff=0.03))
        chips = VGroup(*[chip(t, color=CRIMSON, size=size) for t in targets])
        rule = chip("HPA's rule", size=size)
        formula = T("servers = requests / (600 x target)", 26, SLATE) if not PORTRAIT else VGroup()
        out = stack("servers", "this minute", size=size, buff=0.04, aligned=ORIGIN)
        i0 = W["start_minute"] + 10  # 19:00: the minute of the jump
        views = [("last 10 minutes", W["load"][0:10]), ("yesterday, next 10", W["yesterday"][10:20]),
                 ("last week, next 10", W["last_week"][10:20])]
        rows = []
        if PORTRAIT:
            sw, shh = 2 * SX - 0.05, 0.3
        else:
            sw, shh = 1.2, 0.5
        for label, ys in views:
            frame = Rectangle(width=sw, height=shh, stroke_color=GREY, stroke_width=2, fill_opacity=0)
            b = Box(-sw / 2, -shh / 2, sw / 2, shh / 2, (0, 10), (0, 20000))
            spark = VGroup(frame, b.steps(ys, 0, 10, SLATE, width=4))
            rows.append(VGroup(T(label, 26), spark).arrange(DOWN, buff=0.06, aligned_edge=LEFT) if PORTRAIT else
                        VGroup(spark, T(label, 26)).arrange(RIGHT, buff=0.18))
        for label in ("servers, booting", "queue, time of day"):
            mark = VGroup(*[Square(0.14, stroke_width=0, fill_color=SLATE, fill_opacity=1) for _ in range(3)]).arrange(RIGHT, buff=0.06)
            if PORTRAIT:   # one small mark: three do not fit beside the label in 9:16
                mark = Square(0.14, stroke_width=0, fill_color=SLATE, fill_opacity=1)
            else:
                mark = VGroup(Rectangle(width=sw, height=0.22, stroke_opacity=0, fill_opacity=0), mark)
                mark[1].move_to(mark[0])
            rows.append(VGroup(mark, T(label, 26)).arrange(RIGHT, buff=0.18))
        sees = T(f"it sees, at {hhmm(i0)}:", 26, SLATE)
        if PORTRAIT:
            nobody = stack("Nobody tells it", "how to use them.", size=26, weight="BOLD", buff=0.04)
            chips.arrange_in_grid(rows=2, cols=3, buff=0.12)
            top = VGroup(agent, spell).arrange(RIGHT, buff=0.15)
            column([top, chips, rule, out], hl.get_bottom()[1] - 0.3, TEXT_FLOOR + 0.2, min_gap=0.3)
            for m in (top, chips, rule, out):
                place(m, x=0)
            a1 = arrow(agent.get_bottom(), [agent.get_center()[0], chips.get_top()[1], 0])
            a2 = arrow(chips.get_bottom(), rule.get_top())
            a3 = arrow(rule.get_bottom(), out.get_top())
            block = VGroup(sees, *rows).arrange(DOWN, buff=0.1, aligned_edge=LEFT)
            column([block, nobody], hl.get_bottom()[1] - 0.3, TEXT_FLOOR, left=-SX, min_gap=0.3)
            flow = VGroup(spell, chips, rule, out, a1, a2, a3)
        else:
            nobody = T("Nobody tells it how to use them.", 34, INK, SERIF)
            chips.arrange(RIGHT, buff=0.08)
            place(agent, left=-1.45, top=hl.get_bottom()[1] - 0.35)
            place(spell, left=agent.get_right()[0] + 0.3, top=agent.get_top()[1] + 0.05)
            place(chips, left=agent.get_left()[0], top=spell.get_bottom()[1] - 0.6)
            place(rule, left=chips.get_left()[0], top=chips.get_bottom()[1] - 0.8)
            place(out, left=rule.get_right()[0] + 0.9, y=rule.get_center()[1])
            place(formula, left=rule.get_left()[0], top=rule.get_bottom()[1] - 0.15)
            a1 = arrow(agent.get_bottom(), [agent.get_center()[0], chips.get_top()[1], 0])
            a2 = arrow([rule.get_center()[0], chips.get_bottom()[1], 0], rule.get_top())
            a3 = arrow(rule.get_right(), out.get_left())
            block = VGroup(sees, *rows).arrange(DOWN, buff=0.22, aligned_edge=LEFT)
            place(block, left=-SX, top=hl.get_bottom()[1] - 0.4)
            place(nobody, left=-SX, bottom=-SY + 0.25)
            flow = VGroup()
        pick = SurroundingRectangle(chips[3], buff=0.05, stroke_color=GOLD, stroke_width=8, corner_radius=0.12)
        self.P(FadeIn(hl), FadeIn(agent), FadeIn(spell), rt=0.6)
        self.P(GrowArrow(a1), LaggedStart(*[GrowFromCenter(c) for c in chips], lag_ratio=0.12), rt=1.0)
        self.P(GrowArrow(a2), FadeIn(rule), GrowArrow(a3), FadeIn(out), FadeIn(formula), rt=0.8)
        self.P(Create(pick), rt=0.4)
        for i in (1, 4, 2):
            self.P(pick.animate.move_to(chips[i]), rt=0.5)
            self.wait(0.3)
            self.el += 0.3
        self.at(0.45)
        if PORTRAIT:
            self.P(FadeOut(flow), FadeOut(pick), FadeOut(agent), rt=0.4)
        self.P(FadeIn(sees), LaggedStart(*[AnimationGroup(Create(r[1] if PORTRAIT and k < 3 else r[0]),
                                                          FadeIn(r[0] if PORTRAIT and k < 3 else r[1]))
                                           for k, r in enumerate(rows)], lag_ratio=0.3), rt=2.2)
        self.at(0.84)
        self.P(FadeIn(nobody), *([] if PORTRAIT else [pick.animate.move_to(chips[0])]), rt=0.6)
        self.end()


