class B04_Data(Scene):
    BID, DEFAULT = "B04", 11.16

    def construct(self):
        self.begin()
        S, TD, TR = E["sizes"], E["train_days"], E["training"]
        hl = headline("Real traffic, some of it held out", "Real traffic,", "some held out")
        rowsdef = [("Azure Functions 2019", "Azure Functions", "azure", "apps", SLATE),
                   ("Huawei Cloud 2023, public", "Huawei public", "huawei-public", "functions", TEAL),
                   ("Huawei Cloud 2023, private", "Huawei private", "huawei-private", "functions", TEAL)]
        maxd = max(S[k]["days"] for _, _, k, _, _ in rowsdef)
        unit = ((2 * SX - 0.05) if PORTRAIT else 8.6) / maxd
        bh = 0.36
        groups = []
        for name, sname, key, what, col in rowsdef:
            days, unseen = S[key]["days"], S[key]["unseen_days"]
            if PORTRAIT:
                lab = VGroup(T(sname, 28, col, weight="BOLD"), T(f"{S[key]['test_apps']} of {S[key]['apps']} held out", 26, SLATE)
                             ).arrange(DOWN, buff=0.04, aligned_edge=LEFT)
            else:
                lab = VGroup(T(name, 30, col, weight="BOLD"), T(f"{S[key]['apps']} {what}, {S[key]['test_apps']} held out", 28, SLATE)
                             ).arrange(RIGHT, buff=0.3, aligned_edge=DOWN)
            seen = Rectangle(width=(days - unseen) * unit, height=bh, stroke_width=0, fill_color=col, fill_opacity=1)
            new = Rectangle(width=unseen * unit - 0.04, height=bh - 0.04, stroke_color=col, stroke_width=4, fill_opacity=0)
            dl = T(f"{days} days", 26 if PORTRAIT else 28, weight="BOLD")
            groups.append(VGroup(lab, seen, new, dl))
        key = T("outlined: the last days, unseen in training" if not PORTRAIT else "outlined: new days", 26, SLATE)
        top = hl.get_bottom()[1] - (0.35 if PORTRAIT else 0.35)
        for lab, seen, new, dl in groups:
            place(lab, left=-SX, top=top)
            place(seen, left=-SX, top=lab.get_bottom()[1] - 0.1)
            place(new, left=seen.get_right()[0] + 0.02, y=seen.get_center()[1])
            place(dl, left=new.get_right()[0] + 0.15, y=seen.get_center()[1])
            if dl.get_right()[0] > SX:   # no room on the right: inside the training part of the bar
                dl.set_color(CREAM)
                place(dl, left=seen.get_left()[0] + 0.12, y=seen.get_center()[1])
            top = seen.get_bottom()[1] - (0.3 if PORTRAIT else 0.22)
        place(key, left=-SX, top=top + 0.05)
        tw = (2 * SX) if PORTRAIT else 5.6
        az = Rectangle(width=tw * TD["azure"] / TD["total"], height=bh, stroke_width=0, fill_color=SLATE, fill_opacity=1)
        hw = Rectangle(width=tw * TD["huawei"] / TD["total"], height=bh, stroke_width=0, fill_color=TEAL, fill_opacity=1)
        tbar = VGroup(az, hw).arrange(RIGHT, buff=0)
        ttitle = T(f"{TD['total']} training days", 28, weight="BOLD")
        tlabs = VGroup(T(f"Azure {TD['azure']}", 26, SLATE), T(f"Huawei {TD['huawei']}", 26, TEAL))
        per = len(TR["penalties"]) * TR["seeds"]
        q, qg = (0.19, 0.05) if PORTRAIT else (0.15, 0.035)
        grid = VGroup(squares(per, per, q, qg, NORMAL), squares(per, per, q, qg, MISLEAD)).arrange(DOWN, buff=0.1 if PORTRAIT else 0.2, aligned_edge=LEFT)
        steps = f"{TR['steps'] // 1_000_000}M steps each"
        if PORTRAIT:
            rtitle = stack(f"{TR['runs']} runs on Modal,", steps, size=28, weight="BOLD", buff=0.04)
            rsub = stack(f"{len(TR['penalties'])} penalties x {TR['seeds']} seeds;", "navy: normal history,", "teal: misleading",
                         size=26, color=SLATE, buff=0.04)
            tlabs.arrange(RIGHT, buff=0.3)
            tg = VGroup(ttitle, tbar, tlabs).arrange(DOWN, buff=0.1, aligned_edge=LEFT)
            rg = VGroup(rtitle, grid, rsub).arrange(DOWN, buff=0.12, aligned_edge=LEFT)
            column([tg, rg], hl.get_bottom()[1] - 0.35, TEXT_FLOOR, left=-SX, min_gap=0.35)
            place(tlabs[1], right=SX)
        else:
            rtitle = T(f"{TR['runs']} runs on Modal, {steps}", 26, weight="BOLD")
            rows_l = VGroup(T("normal history", 26, SLATE), T("misleading history", 26, SLATE))
            for lab, row in zip(rows_l, grid):
                place(lab, left=row.get_right()[0] + 0.2, y=row.get_center()[1])
            rsub = T(f"{len(TR['penalties'])} late penalties x {TR['seeds']} seeds each", 26, SLATE)
            tg = VGroup(ttitle, tbar).arrange(DOWN, buff=0.12, aligned_edge=LEFT)
            place(tg, left=-SX, top=key.get_bottom()[1] - 0.4)
            place(tlabs[0], left=-SX, top=tbar.get_bottom()[1] - 0.1)
            place(tlabs[1], right=tbar.get_right()[0], top=tbar.get_bottom()[1] - 0.1)
            gg = VGroup(grid, rows_l)
            rg = VGroup(rtitle, gg, rsub).arrange(DOWN, buff=0.12, aligned_edge=LEFT)
            place(rg, left=-0.25, top=key.get_bottom()[1] - 0.4)
        self.P(FadeIn(hl), rt=0.5)
        for lab, seen, new, dl in groups:
            self.P(FadeIn(lab), GrowFromEdge(seen, LEFT), rt=0.55)
            self.P(Create(new), FadeIn(dl), rt=0.35)
        self.P(FadeIn(key), rt=0.3)
        self.at(0.5)
        if PORTRAIT:
            self.P(FadeOut(VGroup(*groups, key)), rt=0.4)
        self.P(FadeIn(ttitle), GrowFromEdge(az, LEFT), rt=0.5)
        self.P(GrowFromEdge(hw, LEFT), FadeIn(tlabs), rt=0.6)
        self.at(0.64)
        self.P(FadeIn(rtitle), LaggedStart(*[GrowFromCenter(s) for row in grid for s in row], lag_ratio=0.03), rt=1.3)
        self.P(FadeIn(rsub), *([] if PORTRAIT else [FadeIn(rows_l)]), rt=0.4)
        self.end()


