# B05: cost against late requests on the four test sets: HPA at targets 40-90% (line) and the 30 runs
# (dots), results/stress-hpa.json scenario "normal". Each panel shows the cost range around the runs.
# --------------------------------------------------------------------------------------------
PANEL = {"huawei/test_apps": ("Huawei, held-out functions", ("Huawei,", "held-out"), (20500, 31000), 2.5),
         "huawei/test_days": ("Huawei, unseen days", ("Huawei,", "new days"), (20500, 31500), 2.5),
         "azure/test_days": ("Azure, unseen days", ("Azure,", "new days"), (19500, 29000), 2.5),
         "azure/test_apps": ("Azure, held-out apps", ("Azure,", "held-out"), (16500, 24500), 12.5)}


class B05_Frontier(Scene):
    BID, DEFAULT = "B05", 11.56

    def construct(self):
        self.begin()
        hl = headline("Below HPA's line: fewer late requests, same cost", "Below", "HPA's line")
        if PORTRAIT:
            legend = VGroup(swatch(CRIMSON, "HPA, 40-90%"), swatch(NORMAL, "PPO, normal", "dot"),
                            swatch(MISLEAD, "PPO, misleading", "dot")).arrange(DOWN, buff=0.06, aligned_edge=LEFT)
            place(legend, left=-SX, top=hl.get_bottom()[1] - 0.2)
            pw, ph, gx, gy = 1.8, 0.78, 0.3, 0.1
            top0 = legend.get_bottom()[1] - 0.2
        else:
            legend = VGroup(swatch(CRIMSON, "HPA, 40-90%"), swatch(NORMAL, "PPO, normal history", "dot"),
                            swatch(MISLEAD, "PPO, misleading history", "dot")).arrange(RIGHT, buff=0.32)
            place(legend, left=-SX, top=hl.get_bottom()[1] - 0.22)
            pw, ph, gx, gy = 4.85, 1.3, 1.6, 0.25
            top0 = legend.get_bottom()[1] - 0.28
        panels, curves, dots = [], [], []
        row_h = None
        for k, key in enumerate(E["panels"]):
            name, short, xr, ymax = PANEL[key]
            r, c = divmod(k, 2)
            title = stack(*short, size=26, weight="BOLD", buff=0.03) if PORTRAIT else T(name, 28, weight="BOLD")
            x0 = (-SX + c * (pw + gx)) if PORTRAIT else (-SX + 1.05 + c * (pw + gx))
            row_h = row_h or (title.height + 0.12 + ph + gy + (0.0 if PORTRAIT else 0.42))
            ttop = top0 - r * row_h
            place(title, left=x0, top=ttop)
            yt = ttop - title.height - 0.12
            box = Box(x0, yt - ph, x0 + pw, yt, xr, (0, ymax))
            if PORTRAIT:
                ax = axes(box, [(0, ""), (ymax, "")], [])
            else:
                x1, x2 = (xr[0] + 1500) // 1000 * 1000, (xr[1] - 1000) // 1000 * 1000
                ax = axes(box, [(0, "0%"), (ymax, f"{ymax:g}%")], [(x1, f"{x1 // 1000}k"), (x2, f"{x2 // 1000}k")])
            hpa = box.clipped(E["curves"][key], CRIMSON, width=6)
            hdots = VGroup(*[Dot(box.p(x, y), radius=0.07, color=CRIMSON) for x, y in E["curves"][key] if xr[0] <= x <= xr[1] and y <= ymax])
            pts = VGroup(*[Dot(box.p(x, y), radius=0.06 if PORTRAIT else 0.075, color=col)
                           for v, col in (("normal", NORMAL), ("misleading", MISLEAD)) for x, y, _ in E["points"][key][v]])
            panels.append(VGroup(title, ax))
            curves.append(VGroup(hpa, hdots))
            dots.append(pts)
        if PORTRAIT:
            cap = T("x: cost, y: late", 26, SLATE)
            place(cap, left=-SX, top=min(p[1][0].get_bottom()[1] for p in panels[2:]) - 0.15)
        else:
            cap = T("across: server-minutes per day (cost)     up: late requests", 26, SLATE)
            place(cap, left=-SX + 1.05, bottom=-SY + 0.02)
        self.P(FadeIn(hl), FadeIn(legend), *[FadeIn(p) for p in panels], FadeIn(cap), rt=0.8)
        self.P(*[Create(c[0]) for c in curves], *[FadeIn(c[1]) for c in curves], rt=1.0)
        self.at(0.3)
        self.P(LaggedStart(*[LaggedStart(*[GrowFromCenter(d) for d in pts], lag_ratio=0.04) for pts in dots], lag_ratio=0.3), rt=2.4)
        self.end()


# --------------------------------------------------------------------------------------------
# B06: the score card. Each run against HPA at its own cost (frontier.rule_late_at, linear between targets).
# --------------------------------------------------------------------------------------------
def fewer(s):
    """'15% to 57% fewer', or '29% fewer to 33% more' when some runs lose."""
    return f"{-s['hi']}% to {-s['lo']}% fewer" if s["hi"] < 0 else f"{-s['lo']}% fewer to {s['hi']}% more"


def signed(s):
    return f"{s['lo']:+d}% to {s['hi']:+d}%"


class B06_Scorecard(Scene):
    BID, DEFAULT = "B06", 9.64

    def construct(self):
        self.begin()
        S = E["score"]
        hl = headline("Each run against HPA, at the same cost", "Same cost")
        names = {"huawei/test_apps": ("Huawei,", "held-out functions"), "huawei/test_days": ("Huawei,", "unseen days"),
                 "azure/test_days": ("Azure,", "unseen days"), "azure/test_apps": ("Azure,", "held-out apps")}
        short = {"huawei/test_apps": "Huawei held-out", "huawei/test_days": "Huawei unseen days",
                 "azure/test_days": "Azure unseen days", "azure/test_apps": "Azure held-out apps"}
        cols = (("normal", NORMAL), ("misleading", MISLEAD))
        rows, marks = [], []
        if PORTRAIT:
            head = T("runs better, change", 26, SLATE)
            head2 = T("in late requests", 26, SLATE)
            key = VGroup(swatch(NORMAL, "normal history", "dot"), swatch(MISLEAD, "misleading history", "dot")).arrange(DOWN, buff=0.05, aligned_edge=LEFT)
            heads = VGroup(head, head2, key).arrange(DOWN, buff=0.06, aligned_edge=LEFT)
            place(heads, left=-SX, top=hl.get_bottom()[1] - 0.22)
            for p in E["panels"]:
                subs = []
                for v, col in cols:
                    s = S[p][v]
                    dot = Dot(radius=0.11, color=col)
                    subs.append(VGroup(dot, T(f"{s['better']}/{s['runs']}", 26, weight="BOLD"), T(signed(s), 26)).arrange(RIGHT, buff=0.16))
                    marks.append(dot)
                rows.append(VGroup(T(short[p], 26, weight="BOLD"), *subs).arrange(DOWN, buff=0.06, aligned_edge=LEFT))
            for pair in (rows[:2], rows[2:]):   # Huawei first, then Azure in its place
                place(VGroup(*pair).arrange(DOWN, buff=0.45, aligned_edge=LEFT), left=-SX, top=heads.get_bottom()[1] - 0.4)
        else:
            c1, c2 = -2.05, 2.25
            heads = VGroup(VGroup(Dot(radius=0.11, color=NORMAL), stack("trained on", "normal history", size=26, weight="BOLD", buff=0.03)).arrange(RIGHT, buff=0.15),
                           VGroup(Dot(radius=0.11, color=MISLEAD), stack("trained with", "misleading history", size=26, weight="BOLD", buff=0.03)).arrange(RIGHT, buff=0.15))
            place(heads[0], left=c1, top=hl.get_bottom()[1] - 0.25)
            place(heads[1], left=c2, top=hl.get_bottom()[1] - 0.25)
            top = heads.get_bottom()[1] - 0.25
            for p in E["panels"]:
                name = stack(*names[p], size=26, weight="BOLD", buff=0.03)
                cells = []
                for (v, col), x in zip(cols, (c1, c2)):
                    s = S[p][v]
                    cnt = place(T(f"{s['better']} of {s['runs']} runs", 28, weight="BOLD"), left=x, top=top)
                    sq = place(squares(s["runs"], s["better"], 0.16, 0.035, col), left=x, top=cnt.get_bottom()[1] - 0.08)
                    rng = place(T(fewer(s), 26, SLATE), left=x, top=sq.get_bottom()[1] - 0.08)
                    cells.append(VGroup(cnt, rng))
                    marks.append(sq)
                place(name, left=-SX, top=top)
                rows.append(VGroup(name, *cells))
                top = VGroup(name, *cells).get_bottom()[1] - 0.24
        self.P(FadeIn(hl), FadeIn(heads), rt=0.6)
        for i, r in enumerate(rows):
            if i == (2 if PORTRAIT else 3):
                self.at(0.5 if PORTRAIT else 0.55)
            if PORTRAIT and i == 2:
                self.P(FadeOut(VGroup(*rows[:2])), rt=0.3)
            m = marks[2 * i:2 * i + 2]
            if PORTRAIT:   # dots grow; the text fades in
                self.P(FadeIn(VGroup(r[0], r[1][1], r[1][2], r[2][1], r[2][2])), *[GrowFromCenter(g) for g in m], rt=0.7)
            else:
                self.P(FadeIn(r), *[LaggedStart(*[GrowFromCenter(q) for q in g], lag_ratio=0.05) for g in m], rt=0.8)
        self.end()


