# B07: misleading history (scripts/stress.py): yesterday or last week changed before the agent sees it,
# 6 changes x 4 test sets x 15 runs = 360 cases per training variant, each against HPA under the same change.
# --------------------------------------------------------------------------------------------
class B07_Stress(Scene):
    BID, DEFAULT = "B07", 10.26

    def construct(self):
        self.begin()
        ST = E["stress"]
        N, M = ST["normal"], ST["misleading"]
        hl = headline("When history misleads", "History misleads")
        # eight days in outline boxes: seven history days, then the served day (never changed).
        # Each fill is a third of its box, so the 3x change fills the box and nothing grows past it.
        # The changed days are teal, not terracotta: GATE T reads a terracotta block as low-contrast accent text.
        bw, H = (0.4, 0.75) if PORTRAIT else (0.6, 0.9)
        boxes = VGroup(*[Rectangle(width=bw, height=H, stroke_color=GREY, stroke_width=2, fill_opacity=0) for _ in range(8)]
                       ).arrange(RIGHT, buff=0.06)
        fills = VGroup(*[Rectangle(width=bw - 0.04, height=H / 3, stroke_width=0, fill_opacity=1,
                                   fill_color=TEAL if i in (0, 6) else (SLATE if i == 7 else GREY)) for i in range(8)])
        for f, b in zip(fills, boxes):
            place(f, x=b.get_center()[0], bottom=b.get_bottom()[1] + 0.02)
        lw, yd = fills[0], fills[6]
        strip = VGroup(boxes, fills)
        dl = VGroup(T("last week", 26), T("yesterday", 26), T("served day", 26))
        changes = (stack("x0.2: a holiday", "x3: a launch", "x0: a metrics outage", size=28, buff=0.08) if not PORTRAIT else
                   stack("x0.2: a holiday", "x3: a launch", "x0: an outage", size=26, buff=0.04))
        full = (2 * SX) if PORTRAIT else 7.0
        bh = 0.26 if PORTRAIT else 0.4
        bars, labels = [], []
        for s, col, name in ((N, NORMAL, "trained on normal history"), (M, MISLEAD, "trained with misleading history")):
            bg = Rectangle(width=full, height=bh, stroke_color=GREY, stroke_width=2, fill_opacity=0)
            fg = Rectangle(width=full * s["better"] / s["cases"], height=bh, stroke_width=0, fill_color=col, fill_opacity=1)
            place(fg, left=bg.get_left()[0], y=bg.get_center()[1])
            num = T(f"{s['better']} of {s['cases']} cases ({s['pct']}%)" if not PORTRAIT else f"{s['better']} of {s['cases']} ({s['pct']}%)",
                    30 if not PORTRAIT else 26, weight="BOLD")
            nm = T(name if not PORTRAIT else name.split(" ", 2)[2], 28 if not PORTRAIT else 26, SLATE)
            bars.append(VGroup(bg, fg))
            labels.append(VGroup(nm, num))
        if PORTRAIT:
            notes = VGroup(stack("on normal history:", f"{N['normal_better']} vs {M['normal_better']} of {N['normal_runs']} runs", size=26, buff=0.04),
                           stack("worst case vs HPA:", f"+{N['worst']}% vs +{M['worst']}% late", size=26, buff=0.04)).arrange(DOWN, buff=0.08, aligned_edge=LEFT)
            place(dl[0], left=-SX, top=hl.get_bottom()[1] - 0.2)
            place(strip, left=-SX, top=dl[0].get_bottom()[1] - 0.06)
            place(dl[1], right=boxes[6].get_right()[0], top=strip.get_bottom()[1] - 0.06)
            dl.remove(dl[2])
            place(changes, left=-SX, top=dl[1].get_bottom()[1] - 0.25)
            items = [VGroup(lab[0], bar, lab[1]).arrange(DOWN, buff=0.05, aligned_edge=LEFT) for lab, bar in zip(labels, bars)]
            column([*items, notes], dl[1].get_bottom()[1] - 0.22, TEXT_FLOOR, left=-SX, min_gap=0.1)
        else:
            notes = VGroup(T(f"on normal history: {N['normal_better']} and {M['normal_better']} of {N['normal_runs']} runs better", 28),
                           T(f"worst case: {N['worst']}% and {M['worst']}% more late requests than HPA", 28)).arrange(DOWN, buff=0.16, aligned_edge=LEFT)
            place(strip, left=-SX, top=hl.get_bottom()[1] - 0.75)
            place(dl[0], left=-SX, bottom=strip.get_top()[1] + 0.08)
            place(dl[1], x=boxes[6].get_center()[0], bottom=strip.get_top()[1] + 0.08)
            place(dl[2], left=boxes[7].get_left()[0], top=strip.get_bottom()[1] - 0.08)
            place(changes, left=dl[2].get_right()[0] + 0.8, y=strip.get_center()[1])
            items = []
            for lab, bar in zip(labels, bars):
                VGroup(lab[0], bar).arrange(DOWN, buff=0.1, aligned_edge=LEFT)
                place(lab[1], left=bar.get_right()[0] + 0.25, y=bar.get_center()[1])
                items.append(VGroup(lab[0], bar, lab[1]))
            column([*items, notes], dl[2].get_bottom()[1] - 0.4, -SY + 0.25, left=-SX, min_gap=0.3)
        self.P(FadeIn(hl), FadeIn(boxes), *[GrowFromEdge(f, DOWN) for f in fills], FadeIn(dl), rt=0.8)
        for f in (0.2, 3.0, 0.02, 1.0):   # the three changes, then back to the real days
            self.P(lw.animate.stretch_to_fit_height(H / 3 * f, about_edge=DOWN), yd.animate.stretch_to_fit_height(H / 3 * f, about_edge=DOWN), rt=0.45)
        self.P(FadeIn(changes), rt=0.4)
        self.at(0.42)
        if PORTRAIT:
            self.P(FadeOut(changes), rt=0.3)
        self.P(FadeIn(bars[0][0]), FadeIn(labels[0][0]), GrowFromEdge(bars[0][1], LEFT), rt=0.8)
        self.P(FadeIn(labels[0][1]), rt=0.3)
        self.at(0.68)
        self.P(FadeIn(bars[1][0]), FadeIn(labels[1][0]), GrowFromEdge(bars[1][1], LEFT), rt=0.8)
        self.P(FadeIn(labels[1][1]), rt=0.3)
        self.P(FadeIn(notes), rt=0.5)
        self.end()


# --------------------------------------------------------------------------------------------
# B08: the limits. Burstiness (mean |minute-to-minute change| / mean load) of the five Azure held-out
# apps against the median Azure training app; lean vs spare-keeping runs on those apps; simulated servers.
# Portrait swaps the lean/spare rows for the simulated-server card.
# --------------------------------------------------------------------------------------------
class B08_Limits(Scene):
    BID, DEFAULT = "B08", 12.63

    def construct(self):
        self.begin()
        B, LP, C = E["burstiness"], E["azure_apps_by_penalty"], E["cluster"]
        med = B["median"]["azure"]
        hl = headline("The limits", "The limits")
        cap = (stack("burstiness of the 5 Azure held-out apps:", "mean minute-to-minute change / mean load", size=26, color=SLATE, buff=0.04)
               if not PORTRAIT else stack("burstiness of the", "Azure held-out apps;", "dashed: typical", "Azure training app", size=26, color=SLATE, buff=0.04))
        if PORTRAIT:
            place(cap, left=-SX, top=hl.get_bottom()[1] - 0.2)
            y1 = cap.get_bottom()[1] - 0.4
            box = Box(-SX + 0.72, y1 - 1.2, SX - 0.05, y1, (0, 5), (0, 0.3))
        else:
            place(cap, left=-SX, bottom=-SY + 0.08)
            box = Box(-SX + 1.0, -1.25, -0.9, 1.65, (0, 5), (0, 0.3))
        ax = axes(box, [(0, ""), (0.1, "0.1"), (0.2, "0.2"), (0.3, "0.3")], [])
        bars, tags = VGroup(), VGroup()
        for i, v in enumerate(B["held_out"]):
            hot = round(v / med) >= 2
            bars.add(box.column(i + 0.5, 0, v, 0.62, TEAL if hot else GREY))
            if hot:
                tags.add(place(T(f"{v / med:.1f}x" if not PORTRAIT else f"{v / med:.0f}x", 26, weight="BOLD"),
                               x=box.p(i + 0.5, 0)[0], bottom=box.p(0, v)[1] + 0.06))
        mline = DashedLine(box.p(0, med), box.p(5, med), stroke_color=CRIMSON, stroke_width=5, dash_length=0.1)
        mlab = stack("dashed: typical Azure", f"training app ({med:.3f})", size=26, buff=0.04) if not PORTRAIT else VGroup()
        lo, hi = LP["0.01"], LP["1.0"]
        lean = VGroup(T(f"leanest runs: {lo['better']} of {lo['runs']} beat HPA" if not PORTRAIT else f"leanest: {lo['better']} of {lo['runs']} win", 28 if not PORTRAIT else 26),
                      squares(lo["runs"], lo["better"], 0.22, 0.06, SLATE))
        spare = VGroup(T(f"most spare servers: {hi['better']} of {hi['runs']}" if not PORTRAIT else f"most spare: {hi['better']} of {hi['runs']}", 28 if not PORTRAIT else 26),
                       squares(hi["runs"], hi["better"], 0.22, 0.06, SLATE))
        sim_t = T("simulated servers", 30 if not PORTRAIT else 28, weight="BOLD")
        sim = (stack(f"{int(C['capacity'])} requests per minute each", f"{C['boot']}-minute boot", "every request costs the same",
                     "real HPA: usually CPU, every 15 s", size=26, buff=0.08) if not PORTRAIT else
               stack(f"each serves {int(C['capacity'])}", "requests a minute", f"{C['boot']}-minute boot", "same request cost",
                     "real HPA: CPU, 15 s", size=26, buff=0.06))
        body = VGroup(sim_t, sim).arrange(DOWN, buff=0.14, aligned_edge=LEFT)
        if PORTRAIT:   # a slate bar instead of a frame: the frame's padding does not fit 9:16
            frame = Rectangle(width=0.07, height=body.height, stroke_width=0, fill_color=SLATE, fill_opacity=1)
            VGroup(frame, body).arrange(RIGHT, buff=0.18, aligned_edge=UP)
        else:
            frame = SurroundingRectangle(body, buff=0.2, stroke_color=SLATE, stroke_width=4, corner_radius=0.12)
        simg = VGroup(frame, body)
        for g in (lean, spare):
            g.arrange(DOWN, buff=0.08, aligned_edge=LEFT)
        if PORTRAIT:
            ls = VGroup(lean, spare).arrange(DOWN, buff=0.25, aligned_edge=LEFT)
            place(ls, left=-SX, top=box.y0 - 0.25)
            place(simg, left=-SX, top=box.y0 - 0.2)
        else:
            place(mlab, left=box.x0, top=box.y0 - 0.12)
            ls = VGroup(lean, spare).arrange(DOWN, buff=0.3, aligned_edge=LEFT)
            column([ls, simg], hl.get_bottom()[1] - 0.4, cap.get_top()[1] + 0.25, left=0.2, min_gap=0.4)
        self.P(FadeIn(hl), FadeIn(ax), FadeIn(cap), rt=0.6)
        self.P(LaggedStart(*[GrowFromEdge(b, DOWN) for b in bars], lag_ratio=0.15), rt=1.0)
        self.P(Create(mline), FadeIn(mlab), FadeIn(tags), rt=0.6)
        self.at(0.5)
        self.P(FadeIn(lean[0]), LaggedStart(*[GrowFromCenter(q) for q in lean[1]], lag_ratio=0.1), rt=0.6)
        self.P(FadeIn(spare[0]), LaggedStart(*[GrowFromCenter(q) for q in spare[1]], lag_ratio=0.1), rt=0.6)
        self.at(0.74)
        if PORTRAIT:
            self.P(FadeOut(ls), rt=0.3)
        self.P(Create(frame), FadeIn(body), rt=0.7)
        self.end()


# --------------------------------------------------------------------------------------------
# B09: next steps (README Plan).
# --------------------------------------------------------------------------------------------
class B09_Next(Scene):
    BID, DEFAULT = "B09", 8.41

    def construct(self):
        self.begin()
        hl = headline("Next", "Next")
        if PORTRAIT:
            text = ((("Varied traffic",), ("web logs, language", "model serving, with", "balanced training")),
                    (("Server data",), ("Huawei instance and", "CPU data, to tune", "the simulator")),
                    (("History inputs",), ("none, yesterday and", "last week, a longer", "window, or memory")))
        else:
            text = ((("More varied traffic",), ("web server logs and large language model (LLM) serving;",
                                               "training balanced across datasets; a bigger held-out set")),
                    (("Real server data",), ("Huawei's per-minute instance and CPU metrics,", "to calibrate the simulator")),
                    (("Which history inputs help",), ("none, yesterday and last week, a longer window,", "or a model with memory")))
        steps = []
        for i, (title, detail) in enumerate(text):
            badge = VGroup(Circle(radius=0.22 if PORTRAIT else 0.26, stroke_width=0, fill_color=TEAL, fill_opacity=1),
                           T(str(i + 1), 28 if PORTRAIT else 30, CREAM, weight="BOLD"))
            ttl = stack(*title, size=30 if PORTRAIT else 36, weight="BOLD", buff=0.03)
            det = stack(*detail, size=26, color=SLATE, buff=0.04)
            if PORTRAIT:   # badge beside the title, details full width beneath
                steps.append(VGroup(badge, ttl, det))
                VGroup(badge, ttl).arrange(RIGHT, buff=0.25)
                place(det, left=badge.get_left()[0], top=VGroup(badge, ttl).get_bottom()[1] - 0.08)
            else:
                body = VGroup(ttl, det).arrange(DOWN, buff=0.08, aligned_edge=LEFT)
                steps.append(VGroup(badge, ttl, det))
                VGroup(badge, body).arrange(RIGHT, buff=0.3, aligned_edge=UP)
        column(steps, hl.get_bottom()[1] - 0.4, TEXT_FLOOR if PORTRAIT else -SY + 0.2, left=-SX, min_gap=0.18 if PORTRAIT else 0.3)
        def link(i):   # landscape: badge to badge; portrait: through the gap under the details, at the badge's x
            x = steps[i][0].get_center()[0]
            y0 = (steps[i][0].get_bottom() if not PORTRAIT else steps[i][2].get_bottom() + DOWN * 0.06)[1]
            return Line([x, y0, 0], [x, steps[i + 1][0].get_top()[1], 0], stroke_color=TEAL, stroke_width=5)
        spine = VGroup(link(0), link(1))
        self.P(FadeIn(hl), rt=0.5)
        for k, (s, f) in enumerate(zip(steps, (0.0, 0.33, 0.62))):
            self.at(f)
            self.P(GrowFromCenter(s[0][0]), FadeIn(s[0][1]), FadeIn(s[1]), FadeIn(s[2]), *([Create(spine[k - 1])] if k else []), rt=0.6)
        self.end()


# --------------------------------------------------------------------------------------------
# B12: title restate. The full HAI mark, the title with a terracotta period, the handle, the repo.
# --------------------------------------------------------------------------------------------
class B12_Outro(Scene):
    def construct(self):
        self.camera.background_color = CREAM
        D = beat_seconds("B12", 3.24)
        mark = hai_mark(1.1 if PORTRAIT else 1.7)
        title = VGroup(*[T(s, 60 if PORTRAIT else 100, INK, SERIF, t2c={".": TERRA}) for s in ("When to Keep", "Spare Servers.")]
                       ).arrange(DOWN, buff=0.05)
        title.scale_to_fit_width(min(title.width, 2 * SX - 0.1))
        handle = T("@HumanitariansAI", 28 if PORTRAIT else 42, weight="BOLD")
        repo = (stack("github.com/", "lakshdhamija/", "rl-autoscaler", size=26, color=SLATE, buff=0.05, aligned=ORIGIN)
                if PORTRAIT else T("github.com/lakshdhamija/rl-autoscaler", 36, SLATE))
        g = VGroup(mark, title, handle, repo).arrange(DOWN, buff=0.28 if PORTRAIT else 0.4).move_to(ORIGIN)
        if PORTRAIT:
            place(g, top=SY - 0.2)
        rule = Line(LEFT, RIGHT, stroke_color=GOLD, stroke_width=8).set_width(min(title.width, 2 * SX))
        rule.move_to([0, (title.get_bottom()[1] + handle.get_top()[1]) / 2, 0])
        self.play(FadeIn(mark, shift=UP * 0.1), FadeIn(title), run_time=0.6)
        self.play(Create(rule), FadeIn(handle), FadeIn(repo), run_time=0.4)
        self.wait(max(D - 1.0, 0.1))
